  public static <T> JsonParserIterator<T> getThingsFromLeaderNode(
      String query,
      TypeReference<T> typeRef,
      DruidLeaderClient leaderClient,
      ObjectMapper jsonMapper
  )
  {
    Request request;
    InputStreamFullResponseHolder responseHolder;
    try {
      request = leaderClient.makeRequest(
          HttpMethod.GET,
          query
      );

      responseHolder = leaderClient.go(
          request,
          new InputStreamFullResponseHandler()
      );

      if (responseHolder.getStatus().getCode() != HttpServletResponse.SC_OK) {
        throw new RE(
            "Failed to talk to leader node at [%s]. Error code [%d], description [%s].",
            query,
            responseHolder.getStatus().getCode(),
            responseHolder.getStatus().getReasonPhrase()
        );
      }
    }
    catch (IOException | InterruptedException e) {
      throw new RuntimeException(e);
    }

    final JavaType javaType = jsonMapper.getTypeFactory().constructType(typeRef);
    return new JsonParserIterator<>(
        javaType,
        Futures.immediateFuture(responseHolder.getContent()),
        request.getUrl().toString(),
        null,
        request.getUrl().getHost(),
        jsonMapper
    );
  }

  private static <T> CloseableIterator<T> wrap(Iterator<T> iterator, JsonParserIterator<T> it)
    final Request request;
    try {
      request = coordClient.makeRequest(HttpMethod.GET, url)
          .addHeader(HttpHeaders.Names.ACCEPT, MediaType.APPLICATION_JSON);
    }
    catch (IOException e) {
      throw new ISE("Cannot create catalog sync request");
    }
    final StringFullResponseHolder responseHolder;
    try {
      responseHolder = coordClient.go(request);
    }
    catch (IOException e) {
      throw new ISE(e, "Failed to send catalog sync");
    }
    catch (InterruptedException e1) {
      // Treat as a not-found: the only way this exception should occur
      // is during shutdown.
      return null;
    }
    if (responseHolder.getStatus().getCode() == HttpResponseStatus.NOT_FOUND.getCode()) {
      // Not found means the item disappeared. Returning null means "not found".
      return null;
    }
    if (responseHolder.getStatus().getCode() != HttpResponseStatus.OK.getCode()) {
      throw new ISE("Unexpected status from catalog sync: " + responseHolder.getStatus());
    }
    try {
      return smileMapper.readValue(responseHolder.getContent(), typeRef);
    }
    catch (IOException e) {
      throw new ISE(e, "Could not decode the JSON response from catalog sync.");
    }
  }
}

